CREATE OR REPLACE FUNCTION public.accept_invitation(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_inviter uuid;
  v_invited_name text;
begin
  if v_uid is null then raise exception 'authentification requise'; end if;
  select user_id into v_inviter from public.invite_codes where code = upper(trim(p_code));
  if v_inviter is null then
    return jsonb_build_object('accepted', false, 'reason', 'code_inconnu');
  end if;
  if v_inviter = v_uid then
    return jsonb_build_object('accepted', false, 'reason', 'auto_parrainage');
  end if;
  begin
    insert into public.invitations (inviter_id, invited_user_id, code_used)
    values (v_inviter, v_uid, upper(trim(p_code)));
  exception when unique_violation then
    return jsonb_build_object('accepted', false, 'reason', 'deja_parraine');
  end;
  select name into v_invited_name from public.profiles where id = v_uid;
  insert into public.notifications (user_id, type, title, message, priority, target_action)
  values (v_inviter, 'success', 'Invitation acceptée',
          coalesce(v_invited_name, 'Un nouveau membre') || ' a rejoint MokNet grâce à votre invitation.',
          'normal', 'growth');
  return jsonb_build_object('accepted', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.award_xp_and_credits(p_user_id uuid, p_xp_delta integer, p_credits_delta numeric)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.profiles;
  v_new_xp integer;
begin
  -- `auth.uid() is null` est testé EN PREMIER et séparément : sans cela,
  -- l'expression entière vaut NULL pour un appelant anonyme et le garde
  -- ne se déclenche pas (logique ternaire SQL).
  if auth.uid() is null then
    raise exception 'Non autorisé : authentification requise';
  end if;
  if not (auth.uid() = p_user_id or public.is_admin()) then
    raise exception 'Non autorisé';
  end if;

  perform set_config('app.bypass_profile_guard', 'on', true);

  select xp into v_new_xp from public.profiles where id = p_user_id;
  if v_new_xp is null then
    raise exception 'Profil introuvable';
  end if;
  v_new_xp := greatest(0, v_new_xp + p_xp_delta);

  update public.profiles
  set xp = v_new_xp,
      credits = greatest(0, credits + p_credits_delta),
      level = case when v_new_xp >= 1000 then 3 when v_new_xp >= 300 then 2 else 1 end,
      updated_at = now()
  where id = p_user_id
  returning * into v_row;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.can_message_user(p_sender uuid, p_recipient uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pref text;
begin
  if p_sender = p_recipient then
    return true;
  end if;
  if public.are_users_blocked(p_sender, p_recipient) then
    return false;
  end if;

  select coalesce(privacy_settings->>'allowMessagesFrom', 'all') into v_pref
  from public.profiles where id = p_recipient;

  if v_pref = 'none' then
    return false;
  elsif v_pref = 'network' then
    return exists (
      select 1 from public.friendships f
      where f.status = 'accepted'
        and ((f.requester_id = p_sender and f.addressee_id = p_recipient)
          or (f.requester_id = p_recipient and f.addressee_id = p_sender))
    ) or exists (
      select 1 from public.follows fo
      where fo.follower_id = p_sender and fo.followee_id = p_recipient
    );
  else
    return true; -- 'all' (défaut)
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.can_send_friend_request(p_requester uuid, p_addressee uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pref text;
begin
  if public.are_users_blocked(p_requester, p_addressee) then
    return false;
  end if;
  select coalesce(privacy_settings->>'allowFriendRequestsFrom', 'all') into v_pref
    from public.profiles where id = p_addressee;
  if v_pref = 'none' then
    return false;
  end if;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_conversation(p_member_ids uuid[], p_title text DEFAULT NULL::text, p_is_group boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_user_id uuid := auth.uid(); members uuid[]; other_user_id uuid;
  conversation_key text; new_conversation_id uuid;
begin
  if current_user_id is null then raise exception 'Authentication required' using errcode='28000'; end if;
  select coalesce(array_agg(distinct member_id), '{}'::uuid[]) into members
  from unnest(coalesce(p_member_ids, '{}'::uuid[])) member_id
  where member_id is not null and member_id <> current_user_id;
  if cardinality(members) = 0 then raise exception 'At least one other member is required' using errcode='22023'; end if;
  if cardinality(members) > 49 then raise exception 'Conversation member limit exceeded' using errcode='54000'; end if;
  if exists (select 1 from unnest(members) m where not exists (select 1 from public.profiles p where p.id=m))
    then raise exception 'Unknown conversation member' using errcode='23503'; end if;
  if not p_is_group then
    if cardinality(members) <> 1 then raise exception 'A direct conversation has exactly two members' using errcode='22023'; end if;
    other_user_id := members[1];
    conversation_key := least(current_user_id::text, other_user_id::text) || ':' || greatest(current_user_id::text, other_user_id::text);
    insert into public.conversations(is_group,title,created_by,direct_key)
    values(false,null,current_user_id,conversation_key)
    on conflict (direct_key) where is_group=false and direct_key is not null
    do update set updated_at=now() returning id into new_conversation_id;
  else
    if nullif(trim(p_title),'') is null then raise exception 'A group title is required' using errcode='22023'; end if;
    insert into public.conversations(is_group,title,created_by)
    values(true,left(trim(p_title),160),current_user_id) returning id into new_conversation_id;
  end if;
  insert into public.conversation_participants(conversation_id,user_id,member_role)
  values(new_conversation_id,current_user_id,'owner') on conflict(conversation_id,user_id) do nothing;
  insert into public.conversation_participants(conversation_id,user_id,member_role)
  select new_conversation_id,m,'member' from unnest(members) m on conflict(conversation_id,user_id) do nothing;
  return new_conversation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_or_create_invite_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_code text;
begin
  if v_uid is null then raise exception 'authentification requise'; end if;
  select code into v_code from public.invite_codes where user_id = v_uid;
  if v_code is not null then return v_code; end if;
  loop
    v_code := upper(substr(md5(gen_random_uuid()::text), 1, 8));
    begin
      insert into public.invite_codes (user_id, code) values (v_uid, v_code);
      return v_code;
    exception when unique_violation then
      -- collision de code (improbable) : on retente ; user_id déjà pris = course avec soi-même : relire.
      select code into v_code from public.invite_codes where user_id = v_uid;
      if v_code is not null then return v_code; end if;
    end;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_follow_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    update public.profiles set following_count = coalesce(following_count, 0) + 1 where id = new.follower_id;
    update public.profiles set followers_count = coalesce(followers_count, 0) + 1 where id = new.followee_id;
  elsif tg_op = 'DELETE' then
    update public.profiles set following_count = greatest(0, coalesce(following_count, 0) - 1) where id = old.follower_id;
    update public.profiles set followers_count = greatest(0, coalesce(followers_count, 0) - 1) where id = old.followee_id;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.health_apply_remediation(p_remediation_id text, p_line_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_spec jsonb; v_kind text; v_step jsonb; v_rows jsonb;
    v_payload jsonb := '{}'::jsonb; v_order text[] := '{}';
    v_total integer := 0; v_changed integer := 0;
    v_snapshot_id uuid; v_first jsonb;
    v_fn text; v_sig text; v_sigs text[] := '{}';
    v_tbl text; v_tbls text[] := '{}';
begin
    perform public.health_require_general_admin();
    v_spec := public.health_remediation_spec(p_remediation_id);
    if v_spec is null then
        raise exception 'Réparation inconnue : %', p_remediation_id using errcode = '22023';
    end if;
    v_kind := v_spec ->> 'kind';

    if v_kind in ('delete', 'update') then
        for v_step in select * from jsonb_array_elements(v_spec -> 'steps') loop
            execute format(
                'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from public.%I t where %s',
                v_step ->> 'table', v_step ->> 'where') into v_rows;
            v_payload := v_payload || jsonb_build_object(v_step ->> 'table', v_rows);
            v_order := v_order || (v_step ->> 'table');
            v_total := v_total + jsonb_array_length(v_rows);
        end loop;

        insert into public.health_snapshots (remediation_id, line_id, actor_id, kind, payload, restore_order, row_count)
        values (p_remediation_id, p_line_id, auth.uid(), v_kind, v_payload, v_order, v_total)
        returning id into v_snapshot_id;

        v_first := (v_spec -> 'steps') -> 0;
        if v_kind = 'delete' then
            execute format('delete from public.%I where %s', v_first ->> 'table', v_first ->> 'where');
        else
            execute format('update public.%I set %s where %s',
                           v_first ->> 'table', v_first ->> 'set', v_first ->> 'where');
        end if;
        get diagnostics v_changed = row_count;

    elsif v_kind = 'revoke_execute' then
        for v_fn in select jsonb_array_elements_text(v_spec -> 'functions') loop
            for v_sig in
                select p.oid::regprocedure::text
                  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                 where n.nspname = 'public' and p.proname = v_fn and p.prokind = 'f'
                   and has_function_privilege('authenticated', p.oid, 'EXECUTE')
            loop
                v_sigs := v_sigs || v_sig;
            end loop;
        end loop;

        insert into public.health_snapshots (remediation_id, line_id, actor_id, kind, payload, restore_order, row_count)
        values (p_remediation_id, p_line_id, auth.uid(), v_kind,
                jsonb_build_object('signatures', to_jsonb(v_sigs)), '{}', coalesce(array_length(v_sigs, 1), 0))
        returning id into v_snapshot_id;

        foreach v_sig in array v_sigs loop
            execute format('revoke execute on function %s from authenticated', v_sig);
            v_changed := v_changed + 1;
        end loop;

    elsif v_kind = 'revoke_select_anon' then
        for v_tbl in
            select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
             where n.nspname = 'public' and c.relkind = 'r'
               and has_table_privilege('anon', c.oid, 'SELECT')
               and not (c.relname = any (select jsonb_array_elements_text(v_spec -> 'keep')))
        loop
            v_tbls := v_tbls || v_tbl;
        end loop;

        insert into public.health_snapshots (remediation_id, line_id, actor_id, kind, payload, restore_order, row_count)
        values (p_remediation_id, p_line_id, auth.uid(), v_kind,
                jsonb_build_object('tables', to_jsonb(v_tbls)), '{}', coalesce(array_length(v_tbls, 1), 0))
        returning id into v_snapshot_id;

        foreach v_tbl in array v_tbls loop
            execute format('revoke select on public.%I from anon', v_tbl);
            v_changed := v_changed + 1;
        end loop;
    end if;

    return jsonb_build_object(
        'snapshotId', v_snapshot_id, 'changedCount', v_changed, 'snapshotRowCount', v_total);
end;
$function$

CREATE OR REPLACE FUNCTION public.health_diagnose_remediation(p_remediation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_spec jsonb; v_kind text; v_step jsonb;
    v_count integer := 0; v_total integer := 0;
    v_tables text[] := '{}'; v_sample jsonb := '[]'::jsonb;
    v_fn text; v_sigs text[] := '{}';
begin
    perform public.health_require_admin();
    v_spec := public.health_remediation_spec(p_remediation_id);
    if v_spec is null then
        raise exception 'Réparation inconnue : %', p_remediation_id using errcode = '22023';
    end if;
    v_kind := v_spec ->> 'kind';

    if v_kind in ('delete', 'update') then
        for v_step in select * from jsonb_array_elements(v_spec -> 'steps') loop
            execute format('select count(*) from public.%I where %s',
                           v_step ->> 'table', v_step ->> 'where') into v_count;
            v_total := v_total + v_count;
            v_tables := v_tables || (v_step ->> 'table');
            if v_sample = '[]'::jsonb and v_count > 0 then
                execute format(
                    'select coalesce(jsonb_agg(t), ''[]''::jsonb) from (select * from public.%I where %s limit 5) t',
                    v_step ->> 'table', v_step ->> 'where') into v_sample;
            end if;
        end loop;

    elsif v_kind = 'revoke_execute' then
        v_tables := array['pg_proc'];
        for v_fn in select jsonb_array_elements_text(v_spec -> 'functions') loop
            select array_agg(p.oid::regprocedure::text) into v_sigs
              from pg_proc p join pg_namespace n on n.oid = p.pronamespace
             where n.nspname = 'public' and p.proname = v_fn and p.prokind = 'f'
               and has_function_privilege('authenticated', p.oid, 'EXECUTE');
            if v_sigs is not null then
                v_total := v_total + array_length(v_sigs, 1);
                v_sample := v_sample || to_jsonb(v_sigs);
            end if;
        end loop;

    elsif v_kind = 'revoke_select_anon' then
        v_tables := array['information_schema.role_table_grants'];
        select count(*), coalesce(jsonb_agg(to_jsonb(x.table_name)), '[]'::jsonb)
          into v_total, v_sample
          from (
              select c.relname as table_name
                from pg_class c join pg_namespace n on n.oid = c.relnamespace
               where n.nspname = 'public' and c.relkind = 'r'
                 and has_table_privilege('anon', c.oid, 'SELECT')
                 and not (c.relname = any (select jsonb_array_elements_text(v_spec -> 'keep')))
               order by c.relname
          ) x;
    end if;

    return jsonb_build_object(
        'remediationId', p_remediation_id,
        'kind', v_kind,
        'affectedCount', v_total,
        'affectedTables', to_jsonb(v_tables),
        'sample', case when jsonb_array_length(v_sample) > 5
                       then (select jsonb_agg(e) from (select e from jsonb_array_elements(v_sample) e limit 5) s)
                       else v_sample end,
        'reversible', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.health_my_rank()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text;
begin
    if auth.uid() is null then
        return jsonb_build_object('role', null, 'canRead', false, 'canRepair', false);
    end if;
    select role into v_role from public.profiles where id = auth.uid();
    return jsonb_build_object(
        'role', v_role,
        'canRead', v_role in ('admin', 'super_admin'),
        'canRepair', v_role = 'super_admin');
end;
$function$

CREATE OR REPLACE FUNCTION public.health_purge_snapshots(p_older_than_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer;
begin
    perform public.health_require_general_admin();
    delete from public.health_snapshots
     where created_at < now() - make_interval(days => greatest(p_older_than_days, 1));
    get diagnostics v_n = row_count;
    return jsonb_build_object('deleted', v_n);
end;
$function$

CREATE OR REPLACE FUNCTION public.health_require_admin()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if auth.uid() is null then
        raise exception 'Non autorisé : authentification requise.' using errcode = '42501';
    end if;
    if not public.is_admin() then
        raise exception 'Non autorisé : réservé aux administrateurs.' using errcode = '42501';
    end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.health_require_general_admin()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if auth.uid() is null then
        raise exception 'Non autorisé : authentification requise.' using errcode = '42501';
    end if;
    if not exists (
        select 1 from public.profiles
         where id = auth.uid() and role = 'super_admin'
    ) then
        raise exception
            'Non autorisé : cette action est réservée à l''Admin Général (rôle super_admin).'
            using errcode = '42501';
    end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.health_restore_snapshot(p_snapshot_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_snap public.health_snapshots; v_tbl text; v_rows jsonb;
    v_restored integer := 0; v_n integer; v_sig text;
begin
    perform public.health_require_general_admin();
    select * into v_snap from public.health_snapshots where id = p_snapshot_id;
    if v_snap.id is null then
        raise exception 'Sauvegarde introuvable : %', p_snapshot_id using errcode = '22023';
    end if;
    if v_snap.restored_at is not null then
        raise exception 'Cette sauvegarde a déjà été restaurée le %.', v_snap.restored_at using errcode = '22023';
    end if;

    if v_snap.kind in ('delete', 'update') then
        foreach v_tbl in array v_snap.restore_order loop
            v_rows := v_snap.payload -> v_tbl;
            if v_rows is null or jsonb_array_length(v_rows) = 0 then continue; end if;
            execute format(
                'delete from public.%I where id in (select (e ->> ''id'') from jsonb_array_elements($1) e)',
                v_tbl) using v_rows;
            execute format(
                'insert into public.%I select * from jsonb_populate_recordset(null::public.%I, $1)',
                v_tbl, v_tbl) using v_rows;
            get diagnostics v_n = row_count;
            v_restored := v_restored + v_n;
        end loop;

    elsif v_snap.kind = 'revoke_execute' then
        for v_sig in select jsonb_array_elements_text(v_snap.payload -> 'signatures') loop
            execute format('grant execute on function %s to authenticated', v_sig);
            v_restored := v_restored + 1;
        end loop;

    elsif v_snap.kind = 'revoke_select_anon' then
        for v_sig in select jsonb_array_elements_text(v_snap.payload -> 'tables') loop
            execute format('grant select on public.%I to anon', v_sig);
            v_restored := v_restored + 1;
        end loop;
    end if;

    update public.health_snapshots
       set restored_at = now(), restored_by = auth.uid()
     where id = p_snapshot_id;

    return jsonb_build_object('restoredCount', v_restored, 'snapshotId', p_snapshot_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.increment_post_shares(p_post_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ok boolean;
begin
  select (status = 'published' and visibility = 'public') into v_ok
  from public.posts
  where id = p_post_id;

  if v_ok is not true then
    raise exception 'Ce contenu n''est pas partageable (introuvable, non publié, ou non public).';
  end if;

  update public.posts
  set shares_count = coalesce(shares_count, 0) + 1
  where id = p_post_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.insert_wallet_transaction(p_type text, p_amount numeric, p_currency text, p_reference text)
 RETURNS wallet_transactions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_balance numeric;
  v_row public.wallet_transactions;
begin
  if p_type in ('debit','escrow_hold') then
    v_balance := public.get_wallet_balance(auth.uid(), p_currency);
    if v_balance < p_amount then
      raise exception 'Solde insuffisant';
    end if;
  end if;

  insert into public.wallet_transactions (user_id, type, amount, currency, reference)
  values (auth.uid(), p_type, p_amount, p_currency, p_reference)
  returning * into v_row;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.invite_to_live_session(p_session_id uuid, p_invitee_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller uuid := (select auth.uid());
  v_title text;
  v_host_name text;
begin
  if v_caller is null then
    raise exception 'Authentification requise.' using errcode = '42501';
  end if;

  if not is_live_moderator_or_host(p_session_id) then
    raise exception 'Seul l''animateur de ce direct peut inviter quelqu''un.' using errcode = '42501';
  end if;

  if p_invitee_id = v_caller then
    return;
  end if;

  if are_users_blocked(v_caller, p_invitee_id) then
    raise exception 'Invitation impossible.' using errcode = '42501';
  end if;

  select title, coalesce(host_name, '') into v_title, v_host_name
  from live_sessions where id = p_session_id;

  if v_title is null then
    raise exception 'Direct introuvable.' using errcode = 'P0002';
  end if;

  -- L5 — donner l'accès réel (même pour un direct privé), idempotent.
  update live_sessions
  set allowed_member_ids = coalesce(allowed_member_ids, '{}') || p_invitee_id
  where id = p_session_id
    and not (p_invitee_id = any(coalesce(allowed_member_ids, '{}')));

  if exists (
    select 1 from notifications
    where user_id = p_invitee_id
      and type = 'live_invite'
      and target_action = 'live:' || p_session_id::text
      and read = false
  ) then
    return;
  end if;

  insert into notifications (user_id, type, title, message, priority, target_action)
  values (
    p_invitee_id,
    'live_invite',
    'Invitation à un direct',
    coalesce(nullif(v_host_name, ''), 'Un membre') || ' vous invite au direct « ' || v_title || ' »',
    'high',
    'live:' || p_session_id::text
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_conversation_read(p_conversation_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare read_at timestamptz := now();
begin
  update public.conversation_participants set last_read_at=read_at
  where conversation_id=p_conversation_id and user_id=auth.uid();
  if not found then raise exception 'Conversation membership required' using errcode='42501'; end if;
  return read_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_comment_event()
