CREATE OR REPLACE FUNCTION public.notify_friendship_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  requester_name text;
  addressee_name text;
begin
  if TG_OP = 'INSERT' then
    select name into requester_name from public.profiles where id = new.requester_id;
