    insert into public.notifications (user_id, type, title, message, target_action)
    values (new.requester_id, 'success', 'Demande d''ami acceptée', coalesce(addressee_name, 'Un membre') || ' a accepté votre demande d''ami.', 'friends');
  end if;
  return new;
