end;
$function$

CREATE OR REPLACE FUNCTION public.notify_missed_call(p_callee uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller uuid := auth.uid();
  v_caller_name text;
begin
  if v_caller is null or p_callee is null or p_callee = v_caller then
    return;
  end if;

  -- L'appelant doit partager une conversation avec l'appelé (c'est le seul
  -- chemin par lequel un appel peut être lancé) — sinon refus silencieux.
  if not exists (
    select 1
    from public.conversation_participants cp_caller
    join public.conversation_participants cp_callee
      on cp_callee.conversation_id = cp_caller.conversation_id
    where cp_caller.user_id = v_caller
      and cp_callee.user_id = p_callee
  ) then
    return;
  end if;

  if public.are_users_blocked(v_caller, p_callee) then
    return;
  end if;

  select name into v_caller_name from public.profiles where id = v_caller;

  insert into public.notifications (user_id, type, title, message, priority, target_action)
  values (
    p_callee,
    'info',
    'Appel manqué',
    coalesce(v_caller_name, 'Un membre') || ' a essayé de vous appeler.',
    'high',
    'chat'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.post_live_agent_message(p_session_id uuid, p_agent_id text, p_text text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_name   text;
  v_avatar text;
  v_id     uuid;
  v_texte  text := btrim(coalesce(p_text, ''));
begin
  if not public.is_live_moderator_or_host(p_session_id) then
    raise exception 'Seul l''animateur ou un modérateur de ce direct peut faire parler un expert.'
      using errcode = '42501';
  end if;

  if v_texte = '' then
    raise exception 'Un expert ne publie pas un message vide.' using errcode = 'P0001';
  end if;

  select sp.name, sp.avatar into v_name, v_avatar
  from public.live_speakers sp
  where sp.session_id = p_session_id
    and sp.agent_id = p_agent_id
    and sp.left_at is null
  limit 1;

  if v_name is null then
    raise exception 'Cet expert n''est pas sur la scène de ce direct.' using errcode = 'P0001';
  end if;

  insert into public.live_messages (session_id, author_id, author_name, author_avatar, text)
  values (p_session_id, null, v_name, v_avatar, left(v_texte, 4000))
  returning id into v_id;

  return v_id;
end;
$function$

