CREATE OR REPLACE FUNCTION public.store_push_vapid_internal(p_public_key text, p_private_jwk text, p_subject text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
declare
  v_existing text;
  v_secret_id uuid;
begin
  -- Idempotent : une configuration existante n'est jamais écrasée.
  select public_key into v_existing from public.push_vapid_config where id = 'default';
  if v_existing is not null then
    return v_existing;
  end if;
  if p_public_key is null or length(p_public_key) < 80
     or p_private_jwk is null or p_private_jwk !~ '"d"' then
    raise exception 'Clé VAPID invalide';
  end if;
  v_secret_id := vault.create_secret(
    p_private_jwk,
    'push_vapid_private_' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS'),
    'Clé privée VAPID (Web Push) — générée par push-notify, jamais exposée'
  );
  insert into public.push_vapid_config (id, public_key, subject, vault_secret_id)
  values ('default', p_public_key, coalesce(nullif(p_subject, ''), 'https://moknet.net'), v_secret_id);
  return p_public_key;
exception when unique_violation then
  -- Deux premiers appels simultanés : le second renvoie la clé du premier.
  select public_key into v_existing from public.push_vapid_config where id = 'default';
  return v_existing;
end;
$function$

CREATE OR REPLACE FUNCTION public.toggle_message_reaction(p_message_id uuid, p_emoji text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_conversation_id uuid;
  v_reactions jsonb;
  v_users jsonb;
  v_uid_text text := auth.uid()::text;
  v_new_users jsonb;
begin
  select conversation_id, coalesce(metadata->'reactions', '{}'::jsonb)
    into v_conversation_id, v_reactions
    from public.messages where id = p_message_id
    for update;

  if v_conversation_id is null then
    raise exception 'Message introuvable';
  end if;
  if not private.is_conversation_member(v_conversation_id) then
    raise exception 'Non autorise';
  end if;

  v_users := coalesce(v_reactions->p_emoji, '[]'::jsonb);
  if v_users @> to_jsonb(v_uid_text) then
    select coalesce(jsonb_agg(u), '[]'::jsonb) into v_new_users
      from jsonb_array_elements_text(v_users) u where u <> v_uid_text;
  else
    v_new_users := v_users || to_jsonb(v_uid_text);
  end if;

  if jsonb_array_length(v_new_users) = 0 then
    v_reactions := v_reactions - p_emoji;
  else
    v_reactions := jsonb_set(v_reactions, array[p_emoji], v_new_users);
  end if;

  update public.messages set metadata = jsonb_set(coalesce(metadata, '{}'::jsonb), '{reactions}', v_reactions)
    where id = p_message_id;

  return v_reactions;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_my_profile(p_changes jsonb)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_profile public.profiles;
  v_unknown_key text;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if jsonb_typeof(coalesce(p_changes, '{}'::jsonb)) <> 'object' then
    raise exception 'Profile changes must be a JSON object' using errcode = '22023';
  end if;
  if p_changes ? 'interests' and jsonb_typeof(p_changes -> 'interests') <> 'array' then
    raise exception 'interests must be an array' using errcode = '22023';
  end if;
  if p_changes ? 'privacy_settings' and jsonb_typeof(p_changes -> 'privacy_settings') <> 'object' then
    raise exception 'privacy_settings must be an object' using errcode = '22023';
  end if;

  select key into v_unknown_key
  from jsonb_object_keys(coalesce(p_changes, '{}'::jsonb)) as key
  where key <> all(array[
    'name','title','bio','country','city','phone','website','avatar_url',
    'preferred_language','interests','privacy_settings'
  ])
  limit 1;
  if v_unknown_key is not null then
    raise exception 'Profile field is not client-editable: %', v_unknown_key using errcode = '42501';
  end if;

  update public.profiles p set
    name = case when p_changes ? 'name' then coalesce(left(nullif(trim(p_changes->>'name'), ''), 120), p.name) else p.name end,
    title = case when p_changes ? 'title' then left(nullif(trim(p_changes->>'title'), ''), 160) else p.title end,
    bio = case when p_changes ? 'bio' then left(p_changes->>'bio', 2000) else p.bio end,
    country = case when p_changes ? 'country' then left(p_changes->>'country', 120) else p.country end,
    city = case when p_changes ? 'city' then left(p_changes->>'city', 160) else p.city end,
    phone = case when p_changes ? 'phone' then left(p_changes->>'phone', 40) else p.phone end,
    website = case when p_changes ? 'website' then left(p_changes->>'website', 500) else p.website end,
    avatar_url = case when p_changes ? 'avatar_url' then left(p_changes->>'avatar_url', 2000) else p.avatar_url end,
    preferred_language = case when p_changes ? 'preferred_language' then left(p_changes->>'preferred_language', 12) else p.preferred_language end,
    interests = case when p_changes ? 'interests' then array(select jsonb_array_elements_text(p_changes->'interests')) else p.interests end,
    privacy_settings = case when p_changes ? 'privacy_settings' then p_changes->'privacy_settings' else p.privacy_settings end
  where p.id = auth.uid()
  returning p.* into v_profile;

  if v_profile.id is null then
    raise exception 'Profile not found' using errcode = 'P0002';
  end if;
  return v_profile;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_task_dependency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.depends_on_task_id is not null then
    if new.depends_on_task_id = new.id then
      raise exception 'a task cannot depend on itself';
    end if;
    if not exists (
      select 1 from public.tasks
      where id = new.depends_on_task_id and user_id = new.user_id
    ) then
      raise exception 'dependency task not found or belongs to another user';
    end if;
  end if;
  return new;
end;
$function$
